#!/usr/bin/env python3
"""Graph update for the 2026-09-22 MORNING brief (Day 207).
Backup: backups/2026-09-22/graph_v1
Sources: staging/2026-09-22-morning/{intel,markets}.md
Run ONCE. Writes update_log.json + edge_changes.json to the staging dir.
Rules applied: nothing fires on rhetoric; tags respected (CONFIRMED/REPORTED/CLAIMED);
Brent front-month = Nov contract ($100.34 Mon settle / $101.55 live), NOT the rolled $97.33.
"""
import json, os, math
from datetime import date

D = "2026-09-22"
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NODES = os.path.join(ROOT, "graph", "nodes")
EDGES = os.path.join(ROOT, "graph", "edges.json")
STAGE = os.path.join(ROOT, "staging", "2026-09-22-morning")
log, edge_log = [], []


def _load(nid):
    p = os.path.join(NODES, nid + ".json")
    if not os.path.exists(p):
        log.append(("MISSING", nid)); return None, None
    return json.load(open(p)), p


def _save(d, p):
    json.dump(d, open(p, "w"), indent=1, ensure_ascii=False)


def sig(nid, headline):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("recent_signals", []).insert(0, {"date": D, "headline": headline})
    d["last_updated"] = D; _save(d, p); log.append(("SIG", nid))


def current(nid, **kw):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("current", {}).update(kw); d["last_updated"] = D
    _save(d, p); log.append(("CUR", nid))


def summary(nid, text):
    d, p = _load(nid)
    if d is None: return
    d["summary"] = text; d["last_updated"] = D; _save(d, p); log.append(("SUM", nid))


def snapshot(nid, price, trigger):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("price_snapshots", []).append({"date": D, "price": price, "trigger": trigger})
    d["last_updated"] = D; _save(d, p); log.append(("SNAP", nid))


def _find(d, match):
    return [t for t in d.get("active_triggers", []) if match.lower() in str(t.get("condition", "")).lower()]


def trig_set(nid, match, status, note):
    d, p = _load(nid)
    if d is None: return
    hits = _find(d, match)
    if len(hits) != 1:
        log.append(("TRIG-AMBIG", nid, match, len(hits))); return
    t = hits[0]; prior = t.get("notes", "")
    if t.get("status") != status: t["status_changed"] = D
    t["status"] = status
    t["notes"] = note + ("\n[prior] " + prior[:400] if prior else "")
    d["last_updated"] = D; _save(d, p); log.append(("TRIG", nid, match[:40], status))


def trig_note(nid, match, note):
    d, p = _load(nid)
    if d is None: return
    hits = _find(d, match)
    if len(hits) != 1:
        log.append(("TRIG-AMBIG", nid, match, len(hits))); return
    t = hits[0]; prior = t.get("notes", "")
    t["notes"] = note + ("\n[prior] " + prior[:300] if prior else "")
    d["last_updated"] = D; _save(d, p); log.append(("TRIG-REV", nid, match[:40], t.get("status")))


def trig_add(nid, condition, status, cascade, note):
    d, p = _load(nid)
    if d is None: return
    if any(str(t.get("condition", "")).lower()[:55] == condition.lower()[:55] for t in d.get("active_triggers", [])):
        log.append(("TRIG-DUP", nid)); return
    d.setdefault("active_triggers", []).append(
        {"condition": condition, "status": status, "cascade": cascade, "added": D, "notes": note})
    d["last_updated"] = D; _save(d, p); log.append(("TRIG-NEW", nid, condition[:50]))


# ---------- edges ----------
_E = json.load(open(EDGES))
_EIDX = {(x["from"], x["to"]): x for x in _E["edges"]}


def edge(frm, to, new_w, reason, directness=None, etype=None):
    """Set weight on an existing edge (or create). Also mirrors into from-node top_edges if present."""
    key = (frm, to)
    if key in _EIDX:
        x = _EIDX[key]; old = x["weight"]
        x["weight"] = new_w; x["last_activated"] = D
        x["activation_count"] = int(x.get("activation_count") or 0) + 1
        x["context_" + D] = reason
        edge_log.append([frm, to, old, new_w, reason])
    else:
        x = {"from": frm, "to": to, "weight": new_w, "directness": directness or 2, "last_activated": D,
             "type": etype or "new_edge", "added": D, "rationale": reason, "activation_count": 1}
        _E["edges"].append(x); _EIDX[key] = x
        edge_log.append([frm, to, None, new_w, "NEW: " + reason])
    d, p = _load(frm)
    if d is not None:
        for te in d.get("top_edges", []):
            if te.get("to") == to:
                te["weight"] = new_w; te["last_activated"] = D
                te["activation_count"] = int(te.get("activation_count") or 0) + 1
                te["context"] = reason[:500]
        d["last_updated"] = D; _save(d, p)


def save_edges():
    _E["last_updated"] = D
    json.dump(_E, open(EDGES, "w"), indent=1, ensure_ascii=False)


